class Cache
  def initialize(packer: nil)
    @packer = packer
    @storage = {}
  end

  def write(key, payload, stale: false)
    stored_value = @packer ? @packer.dump(payload) : payload
    @storage[key] = { value: stored_value, stale: stale }
  end

  def read(key)
    entry = @storage[key]
    return nil unless entry

    if @packer
      @packer.load(entry[:value])
    else
      entry[:value]
    end
  end

  def sweep
    @storage.delete_if { |_, entry| entry[:stale] }
  end
end
