class Proxy
  def initialize(target)
    @target = target
  end

  def respond_to?(method_name, include_private = false)
    @target.respond_to?(method_name, include_private) || super(method_name, include_private)
  end

  def method(method_name)
    if @target.respond_to?(method_name)
      MethodWrapper.new(@target, method_name)
    else
      super
    end
  end

  def method_missing(method_name, *args, &block)
    if @target.respond_to?(method_name)
      @target.public_send(method_name, *args, &block)
    else
      super
    end
  end

  def respond_to_missing?(method_name, include_private = false)
    @target.respond_to?(method_name, include_private) || super
  end

  class MethodWrapper
    def initialize(target, method_name)
      @target = target
      @method_name = method_name
    end

    def call(*args, &block)
      @target.public_send(@method_name, *args, &block)
    end

    # Make the wrapper behave like a real Method object for arity, etc.
    def arity
      @target.method(@method_name).arity
    end

    def parameters
      @target.method(@method_name).parameters
    end

    def to_proc
      @target.method(@method_name).to_proc
    end

    def inspect
      "#<Method: Proxy::MethodWrapper(#{@method_name})>"
    end

    def to_s
      inspect
    end
  end
end
